{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MapleMonk.Plaeto_wh_AMAZON_VENDOR_PARTNER AS SELECT CAST(asin AS STRING) AS Asin, DATETIME(startTime, \'Asia/Kolkata\') AS StartTime, datetime(endtime,\"Asia/Kolkata\") AS EndTime, CAST(orderedUnits AS INT64) AS OrderedUnits, CAST(orderedRevenue AS float64) AS OrderedRevenue, p.skucode as SKU_CODE, upper(p.PRODUCT_name) as PRODUCT_NAME_Final, Upper(p.CATEGORY) AS Product_Category, Upper(p.category_gender) AS Product_Category_Gender, Upper(p.skucode) AS commonsku, Upper(p.colour_code) AS colour_code, Upper(p.product_code) AS product_code, Upper(p.style_name) AS style_name, Upper(p.sub_style_name) AS sub_style_name, upper(size) as size, upper(size_band) as size_band, upper(Colour) as Colour, upper(Colour_2) as Colour_2 FROM `MapleMonk.Amazon_VC_GET_VENDOR_REAL_TIME_SALES_REPORT` fi left join (select * from ( select master_sku as skucode, marketplace_sku, colour_code, style_code, product_code, category_gender, style_name, sub_style_name, product_name, outsole_colour, category, size, size_band, Colour, Colour_2, fob, mrp, row_number() over (partition by lower(replace(marketplace_sku,\' \',\'\')) order by 1) rw from plaeup-wh.maplemonk.Final_SKU_master where lower(marketplace) like \'%amazon%\') where rw = 1 ) p on lower(replace(fi.asin,\' \',\'\')) = lower(replace(p.marketplace_sku,\' \',\'\')) ; CREATE or replace TABLE plaeup-wh.maplemonk.shipment_status_mapping ( SHIPPING_STATUS string(16777216), Mapped_Status string(16777216) ); Insert INTO plaeup-wh.maplemonk.shipment_status_mapping values (\'DELIVERED\',\'Delivered\'),(\'CANCELLED\',\'Cancelled\'),(\'DELIVERED TO ORIGIN\',\'Returned\'),(\'SHIPMENT CREATED\',\'Shipment Created\'),(\'RETURNED\',\'Returned\'),(\'IN TRANSIT\',\'In Transit\'),(\'DELIVERY DELAYED\',\'In Transit\'),(\'DELIVERED TO ORIGIN\',\'RTO\'),(\'CONFIRMED\',\'Open\'),(\'IN_TRANSIT\',\'In Transit\'),(\'RTO DELIVERED\',\'RTO\'),(\'CANCELED\',\'Cancelled\'),(\'RTO IN TRANSIT\',\'RTO\'),(\'REACHED AT DESTINATION HUB\',\'In Transit\'),(\'PICKED UP\',\'In Transit\'),(\'UNDELIVERED-2ND ATTEMPT\',\'In Transit\'),(\'RTO_OFD\',\'RTO\'),(\'OUT FOR DELIVERY\',\'Out for delivery\'),(\'RTO INITIATED\',\'RTO\'),(\'PICKUP EXCEPTION\',\'Pickup Error\'),(\'CANCELLATION REQUESTED\',\'Pickup Error\'),(\'READY TO SHIP\',\'Ready to Ship\'),(\'OUT_FOR_DELIVERY\',\'Out for delivery\'),(\'SHIPPED\',\'In Transit\'),(\'PICKUP RESCHEDULED\',\'Pickup Error\'),(\'UNDELIVERED-3RD ATTEMPT\',\'In Transit\'),(\'MISROUTED\',\'Misrouted\'),(\'PICKUP SCHEDULED\',\'Pickup Error\'),(\'UNDELIVERED-1ST ATTEMPT\',\'In Transit\'),(\'Not Traceble\',\'Pickup Error\'),(\'UNDELIVERED\',\'In Transit\'),(\'LOST\',\'Lost\'),(\'IN TRANSIT-EN-ROUTE\',\'In Transit\'),(\'Indian Speed Post\',\'Indian Speed Post\'),(\'Exception\',\'Exception\'),(\'Shipment Booked\',\'Pickup Error\'),(\'Assigned\',\'Assigned\'),(\'Pending\',\'Pending\'),(\'PrINT\',\'PrINT\'),(\'IN TRANSIT-AT DESTINATION HUB\',\'In Transit\'),(\'Upcoming\',\'Order Yet To sync\'),(\'RTO-In Transit\',\'RTO\'),(\'PICKUP ERROR\',\'Pickup Error\'),(\'RTO-Out for Delivery\',\'RTO\'),(\'RTO-Delivered\',\'RTO\'),(\'OUT FOR PICKUP\',\'Pickup Error\'),(\'RTO_NDR\',\'RTO\'),(\'RTO-Exception\',\'Exception\'),(\'Delayed\',\'In Transit\'),(\'IN TRANSIT-AT SOURCE HUB\',\'In Transit\'),(\'RTS\',\'Underprocess\'),(\'Manifested\',\'Pickup Error\'),(\'Dispatched\',\'In Transit\'),(\'RTO\',\'RTO\'),(\'Not Picked\',\'Pickup Error\'),(\'DAMAGED\',\'Damaged\'),(\'Closed\',\'Cancelled\'),(\'Open\',\'Open\'),(\'On Hold\',\'On Hold\'),(\'Shipped - Returned to Seller\',\'RTO\'),(\'Shipped - Delivered to Buyer\',\'Delivered\'),(\'Shipped - Picked Up\',\'In Transit\'),(\'Shipped - Rejected by Buyer\',\'RTO\'),(\'Shopify_Processed\',\'Shopify_Processed\'),(\'Ready to dispatch\',\'Ready to Dispatch\'),(\'RTO Undelivered\',\'RTO\'),(\'Shipment Lost\',\'Lost\'),(\'Shipment Error\',\'Shipment Error\'),(\'RTO In-Transit\',\'RTO\'),(\'Dispatch / RTO\',\'RTO\'),(\'Pending Pick-up\',\'Pending\'),(\'Dispatch/Intransit\',\'In Transit\'),(\'Dispatch /Lost and Damange\',\'Lost\'),(\'Dispatch /Undelivered\',\'Undelivered\'),(\'Non serviceable\',\'Non Serviceable\'),(\'Not serviceable\',\'Non Serviceable\'),(\'Dispatch/Delivered\',\'Delivered\'),(\'Refund\',\'Refund\'),(\'F&P\',\'F&P\'),(\'SHIPPED - RETURNING TO SELLER\',\'RTO\'),(\'SHIPPED - LOST IN TRANSIT\',\'Lost\'),(\'SHIPPED - DAMAGED\',\'Damaged\'),(\'SHIPPED - OUT FOR DELIVERY\',\'Out for delivery\'); create table if not exists plaeup-wh.maplemonk.facility_pincode( facility string, pincode string ); create or replace table plaeup-wh.maplemonk.category_mapping ( category string, final_category string ); INSERT INTO plaeup-wh.maplemonk.category_mapping (category, final_category) values (\'OST\', \'OST\'), (\'OVERSIZED T-SHIRT\', \'OST\'), (\'JGR\', \'JGR\'), (\'JOGGERS\', \'JGR\'), (\'PNT\', \'PNT\'), (\'PANTS\', \'PNT\'), (\'HST\', \'HST\'), (\'HALF SLEEVE T-SHIRT\', \'HST\'), (\'SHR\', \'SHR\'), (\'SHIRT\', \'SHR\'), (\'HOD\', \'HOD\'), (\'HOODIE\', \'HOD\'), (\'SWT\', \'SWT\'), (\'SWEATSHIRT\', \'SWT\'), (\'COMBO\', \'COMBO\'), (\'COMBOS\', \'COMBO\'), (\'CTP\', \'CTP\'), (\'CROP TOP\', \'CTP\'), (\'TANK TOP\', \'TANK TOP\'), (\'PULLOVER\', \'PULLOVER\'), (\'CO-ORD\', \'CO-ORD\'), (\'VST\', \'VST\'), (\'VEST\', \'VST\'), (\'JKT\', \'JKT\'), (\'JACKET\', \'JKT\'), (\'SRT\', \'SRT\'), (\'SHORTS\', \'SRT\'), (\'FULL SLEEVE T-SHIRT\', \'FULL SLEEVE T-SHIRT\'), (\'GIFT CARDS\', \'GIFT CARDS\'), (\'TRY\', \'TRY\'), (\'T-SHIRT\', \'TRY\'), (\'BDN\', \'BDN\'), (\'BODYCON\', \'BDN\'), (\'TANK BODYCON\', \'TANK BODYCON\'), (\'BXR\', \'BXR\'), (\'BOXER\', \'BXR\'), (\'RNS\', \'RNS\'), (\'RIBBED TOPS\', \'RNS\'), (\'NA\', \'NA\'); CREATE OR REPLACE TABLE plaeup-wh.maplemonk.marketplace_mapping ( marketplace STRING, final_marketplace STRING ); INSERT INTO plaeup-wh.maplemonk.marketplace_mapping (marketplace, final_marketplace) VALUES (\'FLIPKART_UNITO\', \'Flipkart\'), (\'LIMEROAD\', \'Limeroad\'), (\'MYNTRAPPMP\', \'Myntra\'), (\'PERSONAL\', \'Personal\'), (\'SHOPIFY\', \'Website\'), (\'AMAZON_PRONK\', \'Amazon\'), (\'POPCLUB\', \'Popclub\'), (\'NYKAA FASHION\', \'Nykaa Fashion\'), (\'NYKAA_FASHION\', \'Nykaa Fashion\'), (\'CUSTOM\', \'Custom\'), (\'AJIO_OMNI\', \'Ajio\'), (\'NYKAA_COM\', \'Nykaa.com\'), (\'STUMBL\', \'Stumbl\'), (\'BEWAKOOF\', \'Bewakoof\'), (\'FLIPKART\', \'Flipkart\'), (\'OFFLINE\', \'Offline\'), (\'AMAZON.IN\', \'Amazon\'), (\'WEBSITE\',\'Website\'); create or replace table plaeup-wh.maplemonk.plaeup_wh_sales_consolidated_intermediate as select b.customer_id ,upper(b.SHOP_NAME) SHOP_NAME ,upper(b.marketplace) as marketplace ,Upper(b.FINAL_UTM_CHANNEL) AS CHANNEL ,Upper(coalesce(b.source_name,b.FINAL_UTM_SOURCE)) AS SOURCE ,b.ORDER_ID ,order_name reference_code ,b.PHONE ,b.NAME ,b.EMAIL ,coalesce(cast(b.shipping_status_update_date as timestamp),cast(c.shipping_last_update_date as timestamp), cast(d.shipping_last_update_date as timestamp)) AS SHIPPING_LAST_UPDATE_DATE ,b.SKU ,b.PRODUCT_ID ,Upper(b.PRODUCT_NAME) PRODUCT_NAME ,b.CURRENCY ,Upper(b.CITY) As CITY ,Upper(b.STATE) AS State ,Upper(b.ORDER_STATUS) ORDER_STATUS ,cast(TIMESTAMP(b.ORDER_TIMESTAMP) as date) AS Order_Date ,cast(TIMESTAMP(b.ORDER_TIMESTAMP) as datetime) AS Order_Time ,b.QUANTITY ,b.GROSS_SALES_BEFORE_TAX AS GROSS_SALES_BEFORE_TAX ,b.DISCOUNT_BEFORE_TAX AS DISCOUNT ,b.TAX ,b.SHIPPING_PRICE ,b.TOTAL_SALES AS SELLING_PRICE ,UPPER(coalesce(c.order_status,d.order_status)) as OMS_order_status ,UPPER(coalesce(b.shipping_status, c.shipping_status,d.shipping_status)) AS SHIPPING_STATUS ,upper(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status,d.shipping_status)) FINAL_SHIPPING_STATUS ,cast(b.LINE_ITEM_ID as string) as SALEORDERITEMCODE ,d.sales_order_item_id as SALES_ORDER_ITEM_ID ,coalesce(b.awb,c.awb,d.awb) AWB ,UPPER(REPLACE(IF(ARRAY_LENGTH(GATEWAY) > 0, GATEWAY[OFFSET(0)],\'NA\'), \'\"\', \'\')) PAYMENT_GATEWAY ,upper(coalesce(c.payment_mode,d.payment_mode)) Payment_Mode ,Upper(coalesce(c.Courier,d.courier,b.courier)) AS COURIER ,coalesce(cast(timestamp(b.Shipping_created_at) as date),cast(timestamp(c.manifest_date) as date),cast(timestamp(d.dispatch_date) as date)) AS DISPATCH_DATE ,coalesce(cast(timestamp(c.delivered_date) as date),cast(timestamp(d.delivered_date) as date),case when b.shipping_status like \'delivered\' then cast(timestamp(b.shipping_status_update_date) as date) end) AS DELIVERED_DATE ,case when lower(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status,d.shipping_status)) = \'delivered\' then 1 else 0 end AS DELIVERED_STATUS ,coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end,c.IS_REFUND, d.return_flag) AS RETURN_FLAG ,case when coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end,c.IS_REFUND, d.return_flag) = 1 and lower(b.order_status) not in (\'cancelled\') then ifnull(refund_quantity,0) end returned_quantity ,case when coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end,c.IS_REFUND, d.return_flag) = 1 and lower(b.order_status) not in (\'cancelled\') then ifnull(refund_value,0) end returned_sales ,case when lower(b.order_status) in (\'cancelled\') then cast(quantity as INT64) end cancelled_quantity ,b.shopify_new_customer_flag as NEW_CUSTOMER_FLAG ,Upper(b.shopify_acquisition_product) as acquisition_product ,cast(case when lower(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status,d.shipping_status)) in (\'delivered\',\'delivered to origin\') then date_diff(date(b.ORDER_TIMESTAMP),date(coalesce(cast(b.shipping_status_update_date as timestamp),cast(c.shipping_last_update_date as timestamp), cast(d.shipping_last_update_date as timestamp))),day) when lower(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status,d.shipping_status)) in (\'in transit\', \'shipment created\') then date_diff(date(b.ORDER_TIMESTAMP), CURRENT_DATE(),day) end as INT64) as Days_in_Shipment ,b.shopify_acquisition_date AS MARKETPLACE_ACQUISITION_DATE ,b.SKU_CODE ,UPPER(b.PRODUCT_NAME_FINAL) PRODUCT_NAME_FINAL ,UPPER(coalesce(b.PRODUCT_CATEGORY)) PRODUCT_CATEGORY ,upper(b.Product_Category_Gender) Product_Category_Gender ,b.SKU_CODE commonsku ,upper(coalesce(c.warehouse_name,d.warehouse_name)) WAREHOUSE ,coalesce(b.pincode,d.pincode,c.pincode) as pincode ,coalesce(c.pickup_pincode,fa.pincode) as source_pincode ,b.discount_codes ,b.colour_code ,b.product_code ,b.style_name ,b.sub_style_name ,b.size ,b.size_band ,b.colour ,b.colour_2 ,b.refund_date ,b.refund_value ,b.cancelled_at from plaeup-wh.maplemonk.plaeup_wh_SHOPIFY_FACT_ITEMS b left join (select * from ( select * ,row_number()over(partition by reference_code, Marketplace_LineItem_ID order by last_update_date desc) rw from plaeup-wh.maplemonk.plaeup_wh_EasyEcom_FACT_ITEMS ) z where z.rw = 1 and lower(marketplace) like any (\'%shopify%\') ) c on replace(b.order_name,\'#\',\'\') = c.reference_code and b.LINE_ITEM_ID=c.Marketplace_LineItem_ID left join (select * from (select * ,row_number() over (partition by order_id, SPLIT(saleorderitemcode, \'-\')[OFFSET(0)] order by shipping_last_update_date desc) rw from plaeup-wh.maplemonk.plaeup_wh_UNICOMMERCE_FACT_ITEMS where lower(marketplace) like any (\'%shopify%\')) where rw=1 ) d on b.order_id=d.order_id and b.line_item_id=SPLIT(saleorderitemcode, \'-\')[OFFSET(0)] left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from plaeup-wh.maplemonk.facility_pincode ) where rw = 1 ) fa on lower(d.warehouse_name) = lower(fa.facility) left join ( select * from ( select upper(Shipping_status) shipping_status ,upper(mapped_status) final_shipping_status ,row_number() over (partition by lower(shipping_Status) order by 1) rw from plaeup-wh.maplemonk.shipment_status_mapping ) where rw = 1 ) ShipMap on lower(coalesce(b.shipping_status,c.shipping_status,d.shipping_status,b.ORDER_STATUS)) = lower(ShipMap.shipping_status) LEFT JOIN plaeup-wh.maplemonk.category_mapping cm on upper(cm.category) = upper(b.product_category) UNION ALL SELECT NULL AS customer_id ,UPPER(marketplace) AS shop_name ,UPPER(marketplace) AS marektplace ,UPPER(marketplace) AS CHANNEL ,UPPER(marketplace) AS SOURCE ,ORDER_ID ,reference_code ,phone AS PHONE ,name AS NAME ,email AS EMAIL ,cast(shipping_last_update_date as timestamp) AS SHIPPING_LAST_UPDATE_DATE ,SKU ,b.PRODUCT_ID ,PRODUCT_NAME AS PRODUCT_NAME ,CURRENCY ,UPPER(CITY) AS city ,UPPER(STATE) AS State ,UPPER(ORDER_STATUS) AS order_status ,CAST(ORDER_DATE AS DATE) AS Order_Date ,CAST(ORDER_DATE AS datetime) ORDER_TIME ,SUBORDER_QUANTITY AS QUANTITY ,IFNULL(SELLING_PRICE, 0) - IFNULL(tax, 0) AS gross_sales_before_tax ,DISCOUNT AS DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE AS SELLING_PRICE ,UPPER(ORDER_STATUS) AS OMS_ORDER_STATUS ,UPPER(b.shipping_status) AS SHIPPING_STATUS ,UPPER(COALESCE(shipmap.final_shipping_status, b.shipping_status)) AS FINAL_SHIPPING_STATUS ,saleOrderItemCode AS SALEORDERITEMCODE ,SALES_ORDER_ITEM_ID AS SALES_ORDER_ITEM_ID ,AWB ,NULL AS payment_gateway ,payment_mode ,COURIER ,DISPATCH_DATE AS DISPATCH_DATE ,delivered_date AS delivered_date ,CASE WHEN UPPER(FINAL_SHIPPING_STATUS) IN (\'DELIVERED\') THEN 1 END AS DELIVERED_STATUS ,return_flag AS RETURN_FLAG ,CASE WHEN return_flag = 1 THEN CAST(suborder_quantity AS INT64) END AS returned_quantity ,CASE WHEN return_flag = 1 THEN CAST(selling_price AS FLOAT64) END AS returned_sales ,CASE WHEN return_flag = 0 AND LOWER(order_status) IN (\'cancelled\') THEN CAST(suborder_quantity AS INT64) END AS cancelled_quantity ,CAST(new_customer_flag AS STRING) AS NEW_CUSTOMER_FLAG ,NULL AS ACQUISITION_PRODUCT ,CASE WHEN order_status = \'COMPLETE\' THEN date_diff(CAST(delivered_date AS DATE), CAST(order_date AS DATE),day) ELSE date_diff(CURRENT_DATE(), CAST(order_date AS DATE),day) END AS days_in_shipment ,NULL AS ACQUISITION_DATE ,sku_code ,UPPER(b.product_name_final) AS PRODUCT_NAME_FINAL ,UPPER(coalesce(b.Product_Category)) AS PRODUCT_CATEGORY ,UPPER(b.Product_Category_Gender) AS Product_Category_Gender ,b.commonsku ,UPPER(warehouse_name) AS warehouse ,b.pincode ,fa.pincode source_pincode ,NULL AS discount_codes ,b.colour_code ,b.product_code ,b.style_name ,b.sub_style_name ,b.size ,b.size_band ,b.colour ,b.colour_2 ,null as refund_date ,null as refund_value ,null as cancelled_at FROM plaeup-wh.maplemonk.plaeup_wh_unicommerce_fact_items b left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from plaeup-wh.maplemonk.facility_pincode ) where rw = 1 ) fa on lower(b.warehouse_name) = lower(fa.facility) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM plaeup-wh.maplemonk.shipment_status_mapping ) ShipMap WHERE ShipMap.rw = 1 ) ShipMap ON LOWER(COALESCE(b.shipping_status, b.order_status)) = LOWER(ShipMap.shipping_status) LEFT JOIN plaeup-wh.maplemonk.category_mapping cm on upper(cm.category) = upper(b.product_category) WHERE NOT (LOWER(b.marketplace) LIKE ANY (\'%shopify%\')) UNION ALL SELECT CAST(NULL AS string) AS customer_id, NULL AS Shop_name, \'AMAZON VP\' AS marketplace, \'AMAZON VP\' AS CHANNEL, \'AMAZON VP\' AS SOURCE, concat(Asin,CAST(startTime AS DATE),orderedUnits,orderedRevenue,CAST(endTime AS DATE)) AS ORDER_ID, concat(Asin,CAST(startTime AS DATE),orderedUnits,orderedRevenue,CAST(endTime AS DATE)) AS reference_code, NULL AS PHONE, NULL AS NAME, NULL AS EMAIL, NULL AS SHIPPING_LAST_UPDATE_DATE, NULL AS SKU, asin AS PRODUCT_ID, NULL AS PRODUCT_NAME, NULL AS CURRENCY, NULL AS CITY, NULL AS State, NULL AS Order_Status, CAST(startTime AS DATE) AS Order_Date, CAST(startTime AS DATE) AS Order_Time, orderedUnits AS QUANTITY, orderedRevenue AS GROSS_SALES_BEFORE_TAX, NULL AS DISCOUNT, NULL AS TAX, NULL AS SHIPPING_PRICE, orderedRevenue AS SELLING_PRICE, NULL AS OMS_order_status, NULL AS SHIPPING_STATUS, NULL AS FINAL_SHIPPING_STATUS, concat(Asin,CAST(startTime AS DATE),orderedUnits,orderedRevenue,CAST(endTime AS DATE)) AS SALEORDERITEMCODE, concat(Asin,CAST(startTime AS DATE),orderedUnits,orderedRevenue,CAST(endTime AS DATE)) AS SALES_ORDER_ITEM_ID, NULL AS AWB, NULL AS Payment_Gateway, NULL AS Payment_Mode, NULL AS COURIER, NULL AS DISPATCH_DATE, CAST(endTime AS DATE) AS DELIVERED_DATE, NULL AS DELIVERED_STATUS, NULL AS RETURN_FLAG, NULL AS returned_quantity, NULL AS returned_sales, NULL AS cancelled_quantity, NULL AS NEW_CUSTOMER_FLAG, NULL AS ACQUISITION_PRODUCT, NULL AS Days_in_Shipment, NULL AS ACQUISITION_DATE, ASIN AS SKU_CODE, PRODUCT_NAME_Final, PRODUCT_CATEGORY, Product_Category_Gender, commonsku, NULL AS WAREHOUSE, NULL AS pincode, NULL AS source_pincode, NULL AS discount_codes ,b.colour_code ,b.product_code ,b.style_name ,b.sub_style_name ,b.size ,b.size_band ,b.colour ,b.colour_2 ,null as refund_date ,null as refund_value ,null as cancelled_at FROM MapleMonk.Plaeto_wh_AMAZON_VENDOR_PARTNER b ; CREATE OR REPLACE TABLE plaeup-wh.maplemonk.Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, contact_num, 19700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, phone FROM plaeup-wh.maplemonk.plaeup_wh_sales_consolidated_intermediate ) a ), INT AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, maple_monk_id FROM ( SELECT phone AS contact_num, email FROM plaeup-wh.maplemonk.plaeup_wh_sales_consolidated_intermediate ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10) ) a ) b ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE plaeup-wh.maplemonk.plaeup_wh_sales_consolidated AS SELECT mm.final_marketplace, COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, sum(ifnull(quantity, 0)) over(partition by reference_code order by 1) Order_Quantity, case WHEN upper(m.final_shipping_status) LIKE \'%RTO%\' OR upper(m.final_shipping_status) LIKE \'%FAILURE%\' OR upper(m.order_status) LIKE \'%UNFULFILLABLE%\' OR upper(m.order_status) LIKE \'%RETURNED TO SELLER%\' OR upper(m.order_status) LIKE \'%RETURNING TO SELLER%\' OR upper(m.order_status) LIKE \'%UNDELIVERED%\' OR (upper(m.order_status) LIKE \'%CANCEL%\' AND upper(m.final_shipping_status) = \'IN TRANSIT\') THEN 1 ELSE 0 end as RTO_flag, case when (upper(m.final_shipping_status) like \'%RETURN%\' or upper(m.order_status) = \'RETURNED\') then 1 else 0 end as DTO_flag, case when upper(m.final_shipping_status) like \'%RTO%\' or upper(m.final_shipping_status) like \'%FAILURE%\' or upper(m.order_status) like \'%UNFULFILLABLE%\' or upper(m.order_status) like \'%RETURNED TO SELLER%\' or upper(m.order_status) like \'%RETURNING TO SELLER%\' or upper(m.order_status) like \'%UNDELIVERED%\' or (upper(m.order_status) like \'%CANCEL%\' and upper(m.final_shipping_status) = \'IN TRANSIT\') then m.selling_price ELSE 0 end as RTO_value, case when (upper(m.final_shipping_status) like \'%RETURN%\' or upper(m.order_status) = \'RETURNED\') then m.selling_price else 0 end as DTO_value, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM plaeup-wh.maplemonk.plaeup_wh_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM plaeup-wh.maplemonk.Final_customerID ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, \'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM plaeup-wh.maplemonk.Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email LEFT JOIN plaeup-wh.maplemonk.marketplace_mapping mm ON lower(m.marketplace) = lower(mm.marketplace); ALTER TABLE plaeup-wh.maplemonk.plaeup_wh_sales_consolidated DROP COLUMN IF EXISTS new_customer_flag, DROP COLUMN IF EXISTS acquisition_product; ALTER TABLE plaeup-wh.maplemonk.plaeup_wh_sales_consolidated ADD COLUMN new_customer_flag STRING, ADD COLUMN new_customer_flag_month STRING, ADD COLUMN acquisition_product STRING, ADD COLUMN acquisition_channel STRING, ADD COLUMN acquisition_marketplace STRING; UPDATE plaeup-wh.maplemonk.plaeup_wh_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date THEN \'New\' WHEN Order_Date < first_complete_order_date OR first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date THEN \'Repeat\' END AS Flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM plaeup-wh.maplemonk.plaeup_wh_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw =1; UPDATE plaeup-wh.maplemonk.plaeup_wh_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' WHEN new_customer_flag IS NULL AND LOWER(order_status) IN (\'cancelled\') THEN \'Yet to make completed order\' ELSE new_customer_flag END WHERE new_customer_flag IS NULL; UPDATE plaeup-wh.maplemonk.plaeup_wh_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, order_date, CASE WHEN DATE_TRUNC(order_date, MONTH) = DATE_TRUNC(first_complete_order_date, MONTH) THEN \'New\' WHEN DATE_TRUNC(order_date, MONTH) < DATE_TRUNC(first_complete_order_date, MONTH) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(order_date, MONTH) > DATE_TRUNC(first_complete_order_date, MONTH) THEN \'Repeat\' END AS flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM plaeup-wh.maplemonk.plaeup_wh_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw=1; UPDATE plaeup-wh.maplemonk.plaeup_wh_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; CREATE OR REPLACE TEMPORARY TABLE temp_source_1 AS SELECT customer_id_final, source AS channel, shop_name AS marketplace FROM (SELECT * FROM( SELECT customer_id_final, order_date, source, shop_name, MIN(CASE WHEN LOWER(order_status) <> \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderDate, row_number() over (partition by customer_id_final order by ORDER_TIME) rw FROM plaeup-wh.maplemonk.plaeup_wh_sales_consolidated ) AS res where rw =1 ) WHERE order_date = firstOrderDate; UPDATE plaeup-wh.maplemonk.plaeup_wh_sales_consolidated AS a SET a.acquisition_channel = b.channel FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; UPDATE plaeup-wh.maplemonk.plaeup_wh_sales_consolidated AS a SET a.acquisition_marketplace = b.marketplace FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE temp_product_1 AS SELECT customer_id_final, product_name_final FROM ( SELECT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate, row_number() over (partition by customer_id_final order by ORDER_TIME asc, selling_price desc) rw FROM plaeup-wh.maplemonk.plaeup_wh_sales_consolidated )res WHERE order_date=firstorderdate and rw=1; UPDATE plaeup-wh.maplemonk.plaeup_wh_sales_consolidated AS A SET A.acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE A.customer_id_final = B.customer_id_final; UPDATE plaeup-wh.maplemonk.plaeup_wh_sales_consolidated SET state = CASE WHEN UPPER(state) IN (\'AP\', \'ANDHRA PRADESH\') THEN \'ANDHRA PRADESH\' WHEN UPPER(state) IN (\'AR\', \'ARUNACHAL PRADESH\') THEN \'ARUNACHAL PRADESH\' WHEN UPPER(state) IN (\'AS\', \'ASSAM\') THEN \'ASSAM\' WHEN UPPER(state) IN (\'BR\', \'BIHAR\') THEN \'BIHAR\' WHEN UPPER(state) IN (\'CT\', \'CHHATTISGARH\') THEN \'CHHATTISGARH\' WHEN UPPER(state) IN (\'GA\', \'GOA\') THEN \'GOA\' WHEN UPPER(state) IN (\'GJ\', \'GUJARAT\') THEN \'GUJARAT\' WHEN UPPER(state) IN (\'HR\', \'HARYANA\') THEN \'HARYANA\' WHEN UPPER(state) IN (\'HP\', \'HIMACHAL PRADESH\') THEN \'HIMACHAL PRADESH\' WHEN UPPER(state) IN (\'JH\', \'JHARKHAND\') THEN \'JHARKHAND\' WHEN UPPER(state) IN (\'KA\', \'KARNATAKA\') THEN \'KARNATAKA\' WHEN UPPER(state) IN (\'KL\', \'KERALA\') THEN \'KERALA\' WHEN UPPER(state) IN (\'MP\', \'MADHYA PRADESH\') THEN \'MADHYA PRADESH\' WHEN UPPER(state) IN (\'MH\', \'MAHARASHTRA\') THEN \'MAHARASHTRA\' WHEN UPPER(state) IN (\'MN\', \'MANIPUR\') THEN \'MANIPUR\' WHEN UPPER(state) IN (\'ML\', \'MEGHALAYA\') THEN \'MEGHALAYA\' WHEN UPPER(state) IN (\'MZ\', \'MIZORAM\') THEN \'MIZORAM\' WHEN UPPER(state) IN (\'NL\', \'NAGALAND\') THEN \'NAGALAND\' WHEN UPPER(state) IN (\'OR\', \'ODISHA\') THEN \'ODISHA\' WHEN UPPER(state) IN (\'PB\', \'PUNJAB\') THEN \'PUNJAB\' WHEN UPPER(state) IN (\'RJ\', \'RAJASTHAN\') THEN \'RAJASTHAN\' WHEN UPPER(state) IN (\'SK\', \'SIKKIM\') THEN \'SIKKIM\' WHEN UPPER(state) IN (\'TN\', \'TAMIL NADU\') THEN \'TAMIL NADU\' WHEN UPPER(state) IN (\'TS\', \'TL\', \'TELANGANA\') THEN \'TELANGANA\' WHEN UPPER(state) IN (\'TR\', \'TRIPURA\') THEN \'TRIPURA\' WHEN UPPER(state) IN (\'UP\', \'UTTAR PRADESH\') THEN \'UTTAR PRADESH\' WHEN UPPER(state) IN (\'UT\', \'UK\', \'UTTARAKHAND\') THEN \'UTTARAKHAND\' WHEN UPPER(state) IN (\'WB\', \'WEST BENGAL\') THEN \'WEST BENGAL\' WHEN UPPER(state) IN (\'AN\', \'ANDAMAN AND NICOBAR ISLANDS\', \'ANDAMAN & NICOBAR ISLANDS\') THEN \'ANDAMAN AND NICOBAR ISLANDS\' WHEN UPPER(state) IN (\'CH\', \'CHANDIGARH\') THEN \'CHANDIGARH\' WHEN UPPER(state) IN (\'DN\', \'DADRA AND NAGAR HAVELI\') THEN \'DADRA AND NAGAR HAVELI\' WHEN UPPER(state) IN (\'DD\', \'DAMAN AND DIU\') THEN \'DAMAN AND DIU\' WHEN UPPER(state) IN (\'LD\', \'LAKSHADWEEP\') THEN \'LAKSHADWEEP\' WHEN UPPER(state) IN (\'DL\', \'DELHI\') THEN \'DELHI\' WHEN UPPER(state) IN (\'PY\', \'PUDUCHERRY\') THEN \'PUDUCHERRY\' WHEN UPPER(state) IN (\'JK\', \'JAMMU AND KASHMIR\', \'JAMMU & KASHMIR\') THEN \'JAMMU AND KASHMIR\' WHEN UPPER(state) = \'LADAKH\' THEN \'LADAKH\' ELSE state END WHERE UPPER(state) IN ( \'AP\', \'AR\', \'AS\', \'BR\', \'CT\', \'GA\', \'GJ\', \'HR\', \'HP\', \'JH\', \'KA\', \'KL\', \'MP\', \'MH\', \'MN\', \'ML\', \'MZ\', \'NL\', \'OR\', \'PB\', \'RJ\', \'SK\', \'TN\', \'TS\', \'TL\', \'TR\', \'UP\', \'UT\', \'UK\', \'WB\', \'AN\', \'CH\', \'DN\', \'DD\', \'LD\', \'DL\', \'PY\', \'JK\', \'JAMMU & KASHMIR\', \'ANDAMAN & NICOBAR ISLANDS\' ); create or replace table maplemonk.plaeup_wh_sales_consolidated as select final_marketplace, customer_id_final, acquisition_date, first_complete_order_date, Order_Quantity, RTO_flag, DTO_flag, RTO_value, DTO_value, maple_monk_id_phone, customer_id, SHOP_NAME, marketplace, CHANNEL, SOURCE, ORDER_ID, reference_code, PHONE, NAME, EMAIL, SHIPPING_LAST_UPDATE_DATE, SKU, PRODUCT_ID, PRODUCT_NAME, CURRENCY, CITY, State, ORDER_STATUS, Order_Date, Order_Time, QUANTITY, GROSS_SALES_BEFORE_TAX, DISCOUNT, TAX, SHIPPING_PRICE, SELLING_PRICE, OMS_order_status, SHIPPING_STATUS, FINAL_SHIPPING_STATUS, SALEORDERITEMCODE, SALES_ORDER_ITEM_ID, AWB, PAYMENT_GATEWAY, Payment_Mode, COURIER, DISPATCH_DATE, DELIVERED_DATE, DELIVERED_STATUS, RETURN_FLAG, returned_quantity, returned_sales, cancelled_quantity, Days_in_Shipment, MARKETPLACE_ACQUISITION_DATE, SKU_CODE, PRODUCT_NAME_FINAL, PRODUCT_CATEGORY, PRODUCT_CATEGORY_Gender, commonsku, WAREHOUSE, pincode, source_pincode, discount_codes, new_customer_flag, new_customer_flag_month, acquisition_product, acquisition_channel, acquisition_marketplace, colour_code, product_code, style_name, sub_style_name, size, size_band, colour, colour_2, refund_date, refund_value, null as shopify_refund_value, null as return_tax, from maplemonk.plaeup_wh_sales_consolidated union all select null final_marketplace, null customer_id_final, null acquisition_date, null first_complete_order_date, null Order_Quantity, null RTO_flag, null DTO_flag, null RTO_value, null DTO_value, maple_monk_id_phone, customer_id, SHOP_NAME, marketplace, CHANNEL, SOURCE, null ORDER_ID, null reference_code, null PHONE, null NAME, null EMAIL, null SHIPPING_LAST_UPDATE_DATE, null SKU, null PRODUCT_ID, null PRODUCT_NAME, null CURRENCY, CITY, State, null ORDER_STATUS, refund_date Order_Date, null Order_Time, null QUANTITY, null GROSS_SALES_BEFORE_TAX, null DISCOUNT, null TAX, null SHIPPING_PRICE, null SELLING_PRICE, null OMS_order_status, null SHIPPING_STATUS, null FINAL_SHIPPING_STATUS, null SALEORDERITEMCODE, null SALES_ORDER_ITEM_ID, null AWB, null PAYMENT_GATEWAY, null Payment_Mode, null COURIER, null DISPATCH_DATE, null DELIVERED_DATE, null DELIVERED_STATUS, null RETURN_FLAG, null returned_quantity, null returned_sales, null cancelled_quantity, null Days_in_Shipment, null MARKETPLACE_ACQUISITION_DATE, null SKU_CODE, null PRODUCT_NAME_FINAL, null PRODUCT_CATEGORY, null PRODUCT_CATEGORY_GENDER, null commonsku, null WAREHOUSE, null pincode, null source_pincode, null discount_codes, null new_customer_flag, null new_customer_flag_month, null acquisition_product, null acquisition_channel, null acquisition_marketplace, colour_code, product_code, style_name, sub_style_name, size, size_band, colour, colour_2, refund_date, refund_value, refund_value as shopify_refund_value, tax as return_tax, from maplemonk.plaeup_wh_sales_consolidated where (lower(marketplace) like \'%shopify%\' or lower(marketplace) like \'%website%\') and ifnull(refund_value,0) > 0 ; CREATE TABLE IF NOT EXISTS plaeup-wh.maplemonk.plaeup_wh_easyecom_returns_intermediate ( ORDER_ID INT64, INVOICE_ID INT64, SUBORDER_ID STRING, REFERENCE_CODE STRING, CREDIT_NOTE_ID INT64, ORDER_DATE TIMESTAMP, INVOICE_DATE TIMESTAMP, RETURN_DATE TIMESTAMP, MANIFEST_DATE TIMESTAMP, IMPORT_DATE TIMESTAMP, LAST_UPDATE_DATE TIMESTAMP, COMPANY_PRODUCT_ID STRING, PRODUCTNAME STRING, PRODUCT_ID STRING, SKU STRING, MARKETPLACE STRING, MARKETPLACE_ID INT64, REPLACEMENT_ORDER INT64, RETURN_REASON STRING, RETURNED_QUANTITY FLOAT64, RETURN_AMOUNT_WITHOUT_TAX FLOAT64, RETURN_TAX FLOAT64, RETURN_SHIPPING_CHARGE FLOAT64, RETURN_MISC FLOAT64, TOTAL_RETURN_AMOUNT FLOAT64 ); CREATE OR REPLACE TABLE plaeup-wh.maplemonk.plaeup_wh_easyecom_returns_fact_items AS SELECT IFNULL(FE.Source, \'NA\') AS Marketing_CHANNEL, FR.* FROM plaeup-wh.maplemonk.plaeup_wh_easyecom_returns_intermediate FR LEFT JOIN ( SELECT DISTINCT REPLACE(reference_code, \'#\', \'\') AS REFERENCE_CODE, Source FROM plaeup-wh.maplemonk.plaeup_wh_sales_consolidated ) FE ON FR.REFERENCE_CODE = FE.REFERENCE_CODE; CREATE TABLE IF NOT EXISTS plaeup-wh.maplemonk.plaeup_wh_unicommerce_returns_intermediate ( MARKETPLACE STRING, SOURCE STRING, ORDER_ID STRING, REFERENCE_CODE STRING, PHONE STRING, NAME STRING, EMAIL STRING, ORDER_DATE TIMESTAMP, RETURN_DISPLAYCODE STRING, RETURN_STATUS STRING, INVENTORY_RECEIVED_DATE TIMESTAMP, RETURN_COMPLETE_DATE TIMESTAMP, RETURN_INVOICE_DISPLAY_CODE STRING, RETURN_COURIER STRING, RETURN_PROVIDER_SHIPPING_STATUS STRING, RETURN_TRACKING_NUMBER STRING, RETURN_TYPE STRING, sale_order_item_code STRING, ITEMSKU STRING, ITEM_NAME STRING, INVENTORY_TYPE STRING ); CREATE OR REPLACE TABLE plaeup-wh.maplemonk.plaeup_wh_unicommerce_returns_fact_items AS SELECT IFNULL(FE.channel, \'NA\') AS Marketing_CHANNEL, FE.quantity AS RETURNED_QUANTITY, FE.selling_price AS TOTAL_RETURN_AMOUNT, FE.tax AS RETURN_TAX, FE.selling_price - FE.tax AS RETURN_AMOUNT_WITHOUT_TAX, FR.* FROM (select * from plaeup-wh.maplemonk.plaeup_wh_unicommerce_returns_intermediate where RETURN_DISPLAYCODE is not null) FR LEFT JOIN ( SELECT REPLACE(reference_code, \'#\', \'\') AS REFERENCE_CODE, SALEORDERITEMCODE, channel, Source, SUM(quantity) AS quantity, SUM(selling_price) AS Selling_price, SUM(tax) AS tax FROM plaeup-wh.maplemonk.plaeup_wh_sales_consolidated GROUP BY REFERENCE_CODE, SALEORDERITEMCODE, channel, Source ) FE ON FR.REFERENCE_CODE = FE.REFERENCE_CODE AND FR.sale_order_item_code = FE.SALEORDERITEMCODE; CREATE OR REPLACE TABLE plaeup-wh.maplemonk.plaeup_wh_returns_consolidated AS SELECT UPPER(er.MARKETPLACE) AS Marketplace, mm.FINAL_MARKETPLACE, cast(RETURN_DATE as datetime) return_Date, UPPER(Marketing_CHANNEL) AS Marketing_channel, SUM(RETURNED_QUANTITY) AS TOTAL_RETURNED_QUANTITY, SUM(TOTAL_RETURN_AMOUNT) AS TOTAL_RETURN_AMOUNT, SUM(RETURN_TAX) AS TOTAL_RETURN_TAX, SUM(RETURN_AMOUNT_WITHOUT_TAX) AS TOTAL_RETURN_AMOUNT_EXCL_TAX FROM plaeup-wh.maplemonk.plaeup_wh_easyecom_returns_fact_items er LEFT JOIN (select * from (Select * , row_number() over (partition by lower(marketplace) order by 1) rw from plaeup-wh.maplemonk.marketplace_mapping ) where rw =1 ) mm ON lower(er.marketplace) = lower(mm.marketplace) GROUP BY er.Marketplace, mm.final_marketplace, RETURN_DATE, Marketing_channel UNION ALL SELECT UPPER(fr.MARKETPLACE) AS Marketplace, mm.FINAL_MARKETPLACE, cast(RETURN_COMPLETE_DATE as datetime) AS RETURN_DATE, UPPER(Marketing_CHANNEL) AS Marketing_channel, SUM(RETURNED_QUANTITY) AS TOTAL_RETURNED_QUANTITY, SUM(TOTAL_RETURN_AMOUNT) AS TOTAL_RETURN_AMOUNT, SUM(RETURN_TAX) AS TOTAL_RETURN_TAX, SUM(RETURN_AMOUNT_WITHOUT_TAX) AS TOTAL_RETURN_AMOUNT_EXCL_TAX FROM plaeup-wh.maplemonk.plaeup_wh_unicommerce_returns_fact_items fr LEFT JOIN (select * from (Select * , row_number() over (partition by lower(marketplace) order by 1) rw from plaeup-wh.maplemonk.marketplace_mapping ) where rw =1 ) mm ON lower(fr.marketplace) = lower(mm.marketplace) GROUP BY fr.Marketplace, mm.FINAL_MARKETPLACE, RETURN_COMPLETE_DATE, Marketing_channel;",
                    "transaction": true
                }
            ) }}
